


export type CreateFulfillmentEventRequestInput = { /** Controls buyer email handling. Omit or use send to send when recipient, template, and deduplication rules allow it. Use suppress when another system owns buyer messaging. */ "buyer_notification_behavior"?: "send" | "suppress"; "custom_details"?: Record<string, string>; "event_type": "shipped" | "in_transit" | "out_for_delivery" | "delivered" | "delivery_attempted" | "tracking_updated" | "exception" | "returned" | "custom"; "external_event_id"?: string; "external_status"?: string; "external_system"?: string; "location_description"?: string; "message"?: string; /** Provider event timestamp. Format: date-time. */ "occurred_at"?: string | globalThis.Date; /** Nested package associated with this observational event. Flint resolves and validates its shipment and fulfillment ownership. */ "package_id"?: string; /** Nested shipment associated with this observational event. Flint validates that it belongs to the fulfillment in the path. */ "shipment_id"?: string; };
